849	+func (OKFLinkFormatter) Link(fromDir, targetPath, label string) string {
850	+	cleanTarget := strings.TrimPrefix(ToPosixPath(strings.TrimSpace(targetPath)), "/")
851	+	displayLabel := strings.TrimSpace(label)
852	+	if displayLabel == "" {
853	+		displayLabel = HumanizeSlug(SlugifySegment(strings.TrimSuffix(path.Base(cleanTarget), ".md")))
854	+	}
855	+
856	+	fragment := ""
857	+	if hashIndex := strings.Index(cleanTarget, "#"); hashIndex >= 0 {
858	+		fragment = cleanTarget[hashIndex:]
859	+		cleanTarget = cleanTarget[:hashIndex]
860	+	}
861	+
862	+	cleanFromDir := strings.TrimPrefix(ToPosixPath(strings.TrimSpace(fromDir)), "/")
863	+	if cleanFromDir == "" {
864	+		cleanFromDir = "."
865	+	}
866	+
867	+	relativePath, err := filepath.Rel(filepath.FromSlash(cleanFromDir), filepath.FromSlash(cleanTarget))
868	+	if err != nil {
869	+		relativePath = cleanTarget
870	+	}
871	+	relativePath = ToPosixPath(relativePath)
872	+	if relativePath == "." || relativePath == "" {
873	+		relativePath = path.Base(cleanTarget)
874	+	}
875	+	relativePath = strings.TrimPrefix(relativePath, "./")
876	+	relativePath = markdownLinkTarget(relativePath + fragment)
877	+	return fmt.Sprintf("[%s](%s)", displayLabel, relativePath)
