60	// Promote performs a mechanical, non-destructive wiki-to-OKF conversion.
61	func Promote(ctx context.Context, input PromoteInput) (ConceptResult, error) {
62		if ctx == nil {
63			ctx = context.Background()
64		}
65		if err := ctx.Err(); err != nil {
66			return ConceptResult{}, fmt.Errorf("promote: %w", err)
67		}
68		if input.TargetTopic.Mode != models.TopicModeOKF {
69			return ConceptResult{}, fmt.Errorf("promote: %w: %s", errTargetNotOKFTopic, input.TargetTopic.Slug)
70		}
71		conceptType := strings.TrimSpace(input.Type)
72		if conceptType == "" {
73			return ConceptResult{}, fmt.Errorf("promote: --type is required")
74		}
75		if strings.TrimSpace(input.TargetTopic.RootPath) == "" {
76			return ConceptResult{}, fmt.Errorf("promote: target topic root path is required")
77		}
78	
79		sourcePath, sourceTopicRoot, sourceTopicSlug, sourceRelativePath, err := resolveSourceDocument(input)
80		if err != nil {
81			return ConceptResult{}, fmt.Errorf("promote: %w", err)
82		}
83		_ = sourceTopicRoot
84	
85		sourceBytes, err := os.ReadFile(sourcePath)
86		if err != nil {
87			return ConceptResult{}, fmt.Errorf("promote: read source %q: %w", sourcePath, err)
88		}
89		sourceValues, body, err := frontmatter.Parse(string(sourceBytes))
90		if err != nil {
91			return ConceptResult{}, fmt.Errorf("promote: parse source frontmatter: %w", err)
92		}
93	
94		key := conceptKey(sourceRelativePath)
95		writtenPath, absoluteTargetPath, err := allocateConceptPath(input.TargetTopic.RootPath, key)
96		if err != nil {
97			return ConceptResult{}, fmt.Errorf("promote: allocate concept path: %w", err)
98		}
99	
100		warnings := typeWarnings(conceptType, input.Types)
101		description, descriptionWarnings := resolveDescription(input.Description, body)
102		warnings = append(warnings, descriptionWarnings...)
103		title := strings.TrimSpace(frontmatter.GetString(sourceValues, "title"))
104		if title == "" {
105			title = vault.HumanizeSlug(key)
106		}
107		clock := input.Clock
108		if clock == nil {
109			clock = func() time.Time { return time.Now().UTC() }
110		}
111		now := clock().UTC()
112	
113		transformedBody, rewriteCount, unresolvedLinks := transformWikiLinks(body, sourceTopicSlug, input.TargetTopic.RootPath, path.Dir(writtenPath), writtenPath)
114		values := map[string]any{
115			"description": description,
116			"timestamp":   now.Format(time.RFC3339),
117			"title":       title,
118			"type":        conceptType,
119		}
120		if tags := frontmatter.GetStringSlice(sourceValues, "tags"); len(tags) > 0 {
121			values["tags"] = tags
122		}
123	
124		document, err := frontmatter.Generate(values, transformedBody)
125		if err != nil {
126			return ConceptResult{}, fmt.Errorf("promote: generate concept frontmatter: %w", err)
127		}
128		if err := os.WriteFile(absoluteTargetPath, []byte(document), 0o644); err != nil {
129			return ConceptResult{}, fmt.Errorf("promote: write concept %q: %w", absoluteTargetPath, err)
130		}
131	
132		if err := RegenerateIndex(input.TargetTopic.RootPath); err != nil {
133			return ConceptResult{}, fmt.Errorf("promote: regenerate index: %w", err)
134		}
135		if err := InsertLogEntry(input.TargetTopic.RootPath, now, title, writtenPath, sourceRelativePath); err != nil {
136			return ConceptResult{}, fmt.Errorf("promote: update log: %w", err)
137		}
138	
139		return ConceptResult{
140			WrittenPath:     writtenPath,
141			Type:            conceptType,
142			LinksRewritten:  rewriteCount,
143			UnresolvedLinks: unresolvedLinks,
144			Warnings:        warnings,
145		}, nil
146	}
