148	// Check validates an OKF bundle and returns diagnostics.
149	func Check(ctx context.Context, bundlePath string, options CheckOptions) ([]models.LintIssue, error) {
150		if ctx == nil {
151			ctx = context.Background()
152		}
153		cleanBundlePath := strings.TrimSpace(bundlePath)
154		if cleanBundlePath == "" {
155			return nil, fmt.Errorf("okf check: bundle path is required")
156		}
157		info, err := os.Stat(cleanBundlePath)
158		if err != nil {
159			return nil, fmt.Errorf("okf check: stat bundle path %q: %w", cleanBundlePath, err)
160		}
161		if !info.IsDir() {
162			return nil, fmt.Errorf("okf check: bundle path must be a directory: %s", cleanBundlePath)
163		}
164	
165		typeSet := normalizeTypeSet(options.Types)
166		issues := make([]models.LintIssue, 0)
167		err = filepath.WalkDir(cleanBundlePath, func(currentPath string, entry fs.DirEntry, walkErr error) error {
168			if walkErr != nil {
169				return walkErr
170			}
171			if err := ctx.Err(); err != nil {
172				return err
173			}
174			if currentPath == cleanBundlePath {
175				return nil
176			}
177			if entry.Type()&fs.ModeSymlink != 0 {
178				if entry.IsDir() {
179					return filepath.SkipDir
180				}
181				return nil
182			}
183			if entry.IsDir() {
184				if strings.HasPrefix(entry.Name(), ".") {
185					return filepath.SkipDir
186				}
187				return nil
188			}
189			if !strings.EqualFold(filepath.Ext(entry.Name()), ".md") {
190				return nil
191			}
192	
193			relativePath, err := filepath.Rel(cleanBundlePath, currentPath)
194			if err != nil {
195				return fmt.Errorf("derive relative path for %q: %w", currentPath, err)
196			}
197			relativePath = vault.ToPosixPath(relativePath)
198			switch {
199			case isIndexFile(relativePath):
200				issues = append(issues, checkIndexFile(cleanBundlePath, currentPath, relativePath, options.Strict)...)
201			case isLogFile(relativePath):
202				issues = append(issues, checkLogFile(currentPath, relativePath, options.Strict)...)
203			case isExcludedMarkdown(entry.Name()):
204				return nil
205			default:
206				issues = append(issues, checkConceptFile(currentPath, relativePath, typeSet, options.Strict)...)
207			}
208			return nil
209		})
210		if err != nil {
211			return nil, fmt.Errorf("okf check: %w", err)
212		}
213	
214		sortIssues(issues)
215		return issues, nil
216	}
