248	// RegenerateIndex rewrites the root OKF index from concept frontmatter.
249	func RegenerateIndex(bundlePath string) error {
250		concepts, okfVersion, err := loadConcepts(bundlePath)
251		if err != nil {
252			return err
253		}
254		sort.Slice(concepts, func(i, j int) bool {
255			if concepts[i].Type != concepts[j].Type {
256				return concepts[i].Type < concepts[j].Type
257			}
258			if concepts[i].Title != concepts[j].Title {
259				return concepts[i].Title < concepts[j].Title
260			}
261			return concepts[i].RelativePath < concepts[j].RelativePath
262		})
263	
264		var body strings.Builder
265		body.WriteString("# OKF Bundle Index\n")
266		currentType := ""
267		for _, concept := range concepts {
268			if concept.Type != currentType {
269				currentType = concept.Type
270				body.WriteString("\n## ")
271				body.WriteString(currentType)
272				body.WriteString("\n\n")
273			}
274			body.WriteString("* ")
275			body.WriteString(vault.OKFLinkFormatter{}.Link("", concept.RelativePath, concept.Title))
276			if concept.Description != "" {
277				body.WriteString(" - ")
278				body.WriteString(concept.Description)
279			}
280			body.WriteString("\n")
281		}
282	
283		values := map[string]any{"okf_version": firstNonEmpty(okfVersion, OKFVersion)}
284		content, err := frontmatter.Generate(values, body.String())
285		if err != nil {
286			return fmt.Errorf("generate index frontmatter: %w", err)
287		}
288		if err := os.WriteFile(filepath.Join(bundlePath, "index.md"), []byte(content), 0o644); err != nil {
289			return fmt.Errorf("write index.md: %w", err)
290		}
291		return nil
292	}
