294	// InsertLogEntry inserts a newest-first OKF log entry at the bundle root.
295	func InsertLogEntry(bundlePath string, when time.Time, title, conceptPath, sourcePath string) error {
296		logPath := filepath.Join(bundlePath, "log.md")
297		content, err := os.ReadFile(logPath)
298		if errors.Is(err, os.ErrNotExist) {
299			content = []byte("# Directory Update Log\n")
300		} else if err != nil {
301			return fmt.Errorf("read log.md: %w", err)
302		}
303		entry := fmt.Sprintf(
304			"* **Creation**: Promoted %s from `%s`.",
305			vault.OKFLinkFormatter{}.Link("", conceptPath, strings.TrimSpace(title)),
306			sourcePath,
307		)
308		next := insertLogEntry(string(content), when.UTC().Format(frontmatter.DateLayout), entry)
309		if err := os.WriteFile(logPath, []byte(next), 0o644); err != nil {
310			return fmt.Errorf("write log.md: %w", err)
311		}
312		return nil
313	}
