322	func resolveSourceDocument(input PromoteInput) (absolutePath, topicRoot, topicSlug, topicRelativePath string, err error) {
323		candidates := make([]string, 0, 3)
324		source := strings.TrimSpace(input.SourceDocPath)
325		if source == "" {
326			return "", "", "", "", fmt.Errorf("source document path is required")
327		}
328		if filepath.IsAbs(source) {
329			candidates = append(candidates, source)
330		} else {
331			candidates = append(candidates, source)
332			if strings.TrimSpace(input.VaultPath) != "" {
333				candidates = append(candidates, filepath.Join(input.VaultPath, filepath.FromSlash(source)))
334			}
335		}
336		for _, candidate := range candidates {
337			info, statErr := os.Stat(candidate)
338			if statErr != nil {
339				continue
340			}
341			if info.IsDir() {
342				return "", "", "", "", fmt.Errorf("source document %q must be a file", candidate)
343			}
344			absolutePath, err := filepath.Abs(candidate)
345			if err != nil {
346				return "", "", "", "", fmt.Errorf("resolve source path %q: %w", candidate, err)
347			}
348			topicRoot, topicSlug = discoverTopicRoot(input.VaultPath, absolutePath)
349			if topicRoot != "" {
350				relative, relErr := filepath.Rel(topicRoot, absolutePath)
351				if relErr != nil {
352					return "", "", "", "", fmt.Errorf("derive source topic path: %w", relErr)
353				}
354				return absolutePath, topicRoot, topicSlug, vault.ToPosixPath(relative), nil
355			}
356			return absolutePath, "", "", vault.ToPosixPath(filepath.Base(absolutePath)), nil
357		}
358		return "", "", "", "", fmt.Errorf("source document not found: %s", source)
359	}
360	
361	func discoverTopicRoot(vaultPath, sourcePath string) (string, string) {
362		cleanVault := strings.TrimSpace(vaultPath)
363		current := filepath.Dir(sourcePath)
364		for {
365			if cleanVault != "" && !vault.IsPathInside(cleanVault, current) {
366				return "", ""
367			}
368			if isRegularFile(filepath.Join(current, "CLAUDE.md")) {
369				if cleanVault == "" {
370					return current, filepath.Base(current)
371				}
372				relative, err := filepath.Rel(cleanVault, current)
373				if err != nil {
374					return current, filepath.Base(current)
375				}
376				return current, vault.ToPosixPath(relative)
377			}
378			parent := filepath.Dir(current)
379			if parent == current {
380				break
381			}
382			current = parent
383		}
384		return "", ""
385	}
386	
387	func isRegularFile(filePath string) bool {
388		info, err := os.Stat(filePath)
389		return err == nil && !info.IsDir()
390	}
391	
392	func allocateConceptPath(bundleRoot, key string) (string, string, error) {
393		for suffix := 1; ; suffix++ {
394			name := key
395			if suffix > 1 {
396				name = fmt.Sprintf("%s-%d", key, suffix)
397			}
398			relativePath := name + ".md"
399			absolutePath := filepath.Join(bundleRoot, filepath.FromSlash(relativePath))
400			if _, err := os.Stat(absolutePath); errors.Is(err, os.ErrNotExist) {
401				return relativePath, absolutePath, nil
402			} else if err != nil {
403				return "", "", err
404			}
405		}
406	}
