408	func conceptKey(documentPath string) string {
409		base := path.Base(vault.StripMarkdownExtension(vault.ToPosixPath(documentPath)))
410		return vault.SlugifySegment(base)
411	}
412	
413	func typeWarnings(conceptType string, types []string) []string {
414		typeSet := normalizeTypeSet(types)
415		if len(typeSet) == 0 {
416			return nil
417		}
418		if _, ok := typeSet[conceptType]; ok {
419			return nil
420		}
421		return []string{fmt.Sprintf("type %q is outside the configured OKF vocabulary", conceptType)}
422	}
423	
424	func normalizeTypeSet(types []string) map[string]struct{} {
425		typeSet := make(map[string]struct{})
426		for _, value := range types {
427			value = strings.TrimSpace(value)
428			if value == "" {
429				continue
430			}
431			typeSet[value] = struct{}{}
432		}
433		return typeSet
434	}
435	
436	func resolveDescription(flagValue, body string) (string, []string) {
437		if description := strings.TrimSpace(flagValue); description != "" {
438			return description, nil
439		}
440		if sentence := firstBodySentence(body); sentence != "" {
441			return sentence, nil
442		}
443		return "", []string{"description is empty because the source body has no sentence fallback"}
444	}
445	
446	func firstBodySentence(body string) string {
447		normalized := markdownSyntaxRunes.Replace(markdownLinkPattern.ReplaceAllString(body, " "))
448		normalized = nonSentenceSpace.ReplaceAllString(strings.TrimSpace(normalized), " ")
449		for _, delimiter := range []string{". ", "! ", "? "} {
450			if index := strings.Index(normalized, delimiter); index >= 0 {
451				return strings.TrimSpace(normalized[:index+1])
452			}
453		}
454		return strings.TrimSpace(normalized)
455	}
456	
457	func transformWikiLinks(body, sourceTopicSlug, bundleRoot, fromDir, currentPath string) (string, int, []string) {
458		count := 0
459		unresolved := make([]string, 0)
460		formatter := vault.OKFLinkFormatter{}
461		transformed := wikilinkPattern.ReplaceAllStringFunc(body, func(match string) string {
462			inner := strings.TrimSuffix(strings.TrimPrefix(match, "[["), "]]")
463			target, label := splitWikiLink(inner)
464			targetPath := mappedTargetPath(target, sourceTopicSlug)
465			if strings.TrimSpace(label) == "" {
466				label = fallbackWikiLabel(target)
467			}
468			count++
469			if stripFragment(targetPath) != stripFragment(currentPath) && !isRegularFile(filepath.Join(bundleRoot, filepath.FromSlash(stripFragment(targetPath)))) {
470				unresolved = append(unresolved, targetPath)
471			}
472			return formatter.Link(fromDir, targetPath, label)
473		})
474		sort.Strings(unresolved)
475		return transformed, count, dedupeStrings(unresolved)
476	}
477	
478	func splitWikiLink(inner string) (string, string) {
479		parts := strings.SplitN(inner, "|", 2)
480		target := strings.TrimSpace(parts[0])
481		if len(parts) == 1 {
482			return target, ""
483		}
484		return target, strings.TrimSpace(parts[1])
485	}
486	
487	func mappedTargetPath(target, sourceTopicSlug string) string {
488		target = vault.ToPosixPath(strings.TrimSpace(target))
489		fragment := ""
490		if before, after, found := strings.Cut(target, "#"); found {
491			target = before
492			fragment = "#" + after
493		}
494		target = strings.TrimPrefix(target, "/")
495		if sourceTopicSlug != "" {
496			prefix := strings.Trim(sourceTopicSlug, "/") + "/"
497			target = strings.TrimPrefix(target, prefix)
498		}
499		return conceptKey(target) + ".md" + fragment
500	}
501	
502	func stripFragment(target string) string {
503		if before, _, found := strings.Cut(target, "#"); found {
504			return before
505		}
506		return target
507	}
508	
509	func fallbackWikiLabel(target string) string {
510		target = stripFragment(target)
511		return vault.HumanizeSlug(conceptKey(target))
512	}
513	
514	func dedupeStrings(values []string) []string {
515		if len(values) == 0 {
516			return nil
517		}
518		deduped := values[:0]
519		var previous string
520		for index, value := range values {
521			if index > 0 && value == previous {
522				continue
523			}
524			deduped = append(deduped, value)
525			previous = value
526		}
527		return append([]string(nil), deduped...)
528	}
529	
530	func loadConcepts(bundlePath string) ([]conceptInfo, string, error) {
531		okfVersion := OKFVersion
532		indexPath := filepath.Join(bundlePath, "index.md")
533		if content, err := os.ReadFile(indexPath); err == nil {
534			values, _, parseErr := frontmatter.Parse(string(content))
535			if parseErr != nil {
536				return nil, "", fmt.Errorf("parse index.md: %w", parseErr)
537			}
538			if version := strings.TrimSpace(frontmatter.GetString(values, "okf_version")); version != "" {
539				okfVersion = version
540			}
541		} else if !errors.Is(err, os.ErrNotExist) {
542			return nil, "", fmt.Errorf("read index.md: %w", err)
543		}
544	
545		concepts := make([]conceptInfo, 0)
546		err := filepath.WalkDir(bundlePath, func(currentPath string, entry fs.DirEntry, walkErr error) error {
547			if walkErr != nil {
548				return walkErr
549			}
550			if currentPath == bundlePath {
551				return nil
552			}
553			if entry.Type()&fs.ModeSymlink != 0 {
554				if entry.IsDir() {
555					return filepath.SkipDir
556				}
557				return nil
558			}
559			if entry.IsDir() {
560				if strings.HasPrefix(entry.Name(), ".") {
561					return filepath.SkipDir
562				}
563				return nil
564			}
565			if !strings.EqualFold(filepath.Ext(entry.Name()), ".md") || isExcludedMarkdown(entry.Name()) {
566				return nil
567			}
568			relativePath, err := filepath.Rel(bundlePath, currentPath)
569			if err != nil {
570				return err
571			}
572			relativePath = vault.ToPosixPath(relativePath)
573			if isIndexFile(relativePath) || isLogFile(relativePath) {
574				return nil
575			}
576			content, err := os.ReadFile(currentPath)
577			if err != nil {
578				return err
579			}
580			values, _, err := frontmatter.Parse(string(content))
581			if err != nil || len(values) == 0 {
582				return nil
583			}
584			conceptType := strings.TrimSpace(frontmatter.GetString(values, "type"))
585			title := strings.TrimSpace(frontmatter.GetString(values, "title"))
586			if title == "" {
587				title = vault.HumanizeSlug(conceptKey(relativePath))
588			}
589			concepts = append(concepts, conceptInfo{
590				RelativePath: relativePath,
591				Type:         firstNonEmpty(conceptType, "Concept"),
592				Title:        title,
593				Description:  strings.TrimSpace(frontmatter.GetString(values, "description")),
594			})
595			return nil
596		})
597		if err != nil {
598			return nil, "", fmt.Errorf("scan concepts: %w", err)
599		}
600		return concepts, okfVersion, nil
601	}
602	
603	func checkConceptFile(filePath, relativePath string, typeSet map[string]struct{}, strict bool) []models.LintIssue {
604		content, err := os.ReadFile(filePath)
605		if err != nil {
606			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("read concept: %v", err))}
607		}
608		values, _, err := frontmatter.Parse(string(content))
609		if err != nil {
610			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("frontmatter is invalid: %v", err))}
611		}
612		if len(values) == 0 {
613			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "type", "concept must start with YAML frontmatter")}
614		}
615		issues := make([]models.LintIssue, 0)
616		conceptType := strings.TrimSpace(frontmatter.GetString(values, "type"))
617		if conceptType == "" {
618			issues = append(issues, newIssue(models.SeverityError, relativePath, "type", "concept frontmatter must include non-empty type"))
619		}
620		for _, field := range []string{"title", "description", "timestamp"} {
621			if strings.TrimSpace(frontmatter.GetString(values, field)) == "" {
622				issues = append(issues, newIssue(warningSeverity(strict), relativePath, field, fmt.Sprintf("producer field %q is missing", field)))
623			}
624		}
625		if len(typeSet) > 0 && conceptType != "" {
626			if _, ok := typeSet[conceptType]; !ok {
627				issues = append(issues, newIssue(warningSeverity(strict), relativePath, "type", fmt.Sprintf("type %q is outside the configured OKF vocabulary", conceptType)))
628			}
629		}
630		return issues
631	}
632	
633	func checkIndexFile(bundlePath, filePath, relativePath string, strict bool) []models.LintIssue {
634		content, err := os.ReadFile(filePath)
635		if err != nil {
636			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("read index: %v", err))}
637		}
638		values, _, err := frontmatter.Parse(string(content))
639		if err != nil {
640			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("index frontmatter is invalid: %v", err))}
641		}
642		if len(values) == 0 {
643			return nil
644		}
645		if relativePath != "index.md" {
646			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "frontmatter", "only the bundle-root index.md may declare okf_version frontmatter")}
647		}
648		for key := range values {
649			if key != "okf_version" {
650				return []models.LintIssue{newIssue(models.SeverityError, relativePath, key, "root index.md frontmatter may only contain okf_version")}
651			}
652		}
653		_ = bundlePath
654		_ = strict
655		return nil
656	}
657	
658	func checkLogFile(filePath, relativePath string, strict bool) []models.LintIssue {
659		content, err := os.ReadFile(filePath)
660		if err != nil {
661			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("read log: %v", err))}
662		}
663		issues := make([]models.LintIssue, 0)
664		for line := range strings.SplitSeq(string(content), "\n") {
665			trimmed := strings.TrimSpace(line)
666			if !strings.HasPrefix(trimmed, "## ") {
667				continue
668			}
669			dateValue := strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
670			if _, err := time.Parse(frontmatter.DateLayout, dateValue); err != nil {
671				issues = append(issues, newIssue(models.SeverityError, relativePath, "date", fmt.Sprintf("log heading %q must use YYYY-MM-DD", trimmed)))
672			}
673		}
674		_ = strict
675		return issues
676	}
677	
678	func newIssue(severity models.DiagnosticSeverity, filePath, target, message string) models.LintIssue {
679		return models.LintIssue{
680			Kind:     models.LintIssueKindFormat,
681			Severity: severity,
682			FilePath: filePath,
683			Target:   target,
684			Message:  message,
685		}
686	}
687	
688	func warningSeverity(strict bool) models.DiagnosticSeverity {
689		if strict {
690			return models.SeverityError
691		}
692		return models.SeverityWarning
693	}
694	
695	func sortIssues(issues []models.LintIssue) {
696		sort.Slice(issues, func(i, j int) bool {
697			if issues[i].Severity != issues[j].Severity {
698				return issues[i].Severity < issues[j].Severity
699			}
700			if issues[i].FilePath != issues[j].FilePath {
701				return issues[i].FilePath < issues[j].FilePath
702			}
703			if issues[i].Target != issues[j].Target {
704				return issues[i].Target < issues[j].Target
705			}
706			return issues[i].Message < issues[j].Message
707		})
708	}
709	
710	func isIndexFile(relativePath string) bool {
711		return strings.EqualFold(path.Base(vault.ToPosixPath(relativePath)), "index.md")
712	}
713	
714	func isLogFile(relativePath string) bool {
715		return strings.EqualFold(path.Base(vault.ToPosixPath(relativePath)), "log.md")
716	}
717	
718	func isExcludedMarkdown(name string) bool {
719		lower := strings.ToLower(strings.TrimSpace(name))
720		switch lower {
721		case "claude.md", "agents.md", "readme.md", "license.md", "notice.md", "attribution.md":
722			return true
723		default:
724			return strings.HasPrefix(lower, "license.") || strings.HasPrefix(lower, "notice.") || strings.HasPrefix(lower, "attribution.")
725		}
726	}
727	
728	func insertLogEntry(content, dateHeading, entry string) string {
729		lines := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
730		if len(lines) == 0 || strings.TrimSpace(lines[0]) == "" {
731			lines = []string{"# Directory Update Log"}
732		}
733		heading := "## " + dateHeading
734		for index, line := range lines {
735			if strings.TrimSpace(line) != heading {
736				continue
737			}
738			next := append([]string{}, lines[:index+1]...)
739			next = append(next, entry)
740			next = append(next, lines[index+1:]...)
741			return strings.TrimRight(strings.Join(next, "\n"), "\n") + "\n"
742		}
743		next := []string{strings.TrimRight(strings.Join(lines[:1], "\n"), "\n"), "", heading, "", entry}
744		if len(lines) > 1 {
745			rest := strings.TrimSpace(strings.Join(lines[1:], "\n"))
746			if rest != "" {
747				next = append(next, "", rest)
748			}
749		}
750		return strings.TrimRight(strings.Join(next, "\n"), "\n") + "\n"
751	}
752	
753	func firstNonEmpty(values ...string) string {
754		for _, value := range values {
755			if trimmed := strings.TrimSpace(value); trimmed != "" {
756				return trimmed
757			}
758		}
759		return ""
760	}
