1	// Package frontmatter provides helpers for parsing and generating YAML frontmatter in markdown documents.
2	package frontmatter
3	
4	import (
5		"fmt"
6		"reflect"
7		"regexp"
8		"sort"
9		"strconv"
10		"strings"
11		"time"
12	
13		"gopkg.in/yaml.v3"
14	)
15	
16	const (
17		// DateLayout matches the KB schema date fields.
18		DateLayout = "2006-01-02"
19	)
20	
21	// ErrorKind identifies the failure class for frontmatter operations.
22	type ErrorKind string
23	
24	const (
25		ErrorKindMissingClosingDelimiter ErrorKind = "missing_closing_delimiter"
26		ErrorKindInvalidYAML             ErrorKind = "invalid_yaml"
27		ErrorKindUnsupportedValue        ErrorKind = "unsupported_value"
28	)
29	
30	var yamlLinePattern = regexp.MustCompile(`line (\d+)`)
31	
32	// Error reports structured parse and generation failures.
33	type Error struct {
34		Kind ErrorKind
35		Key  string
36		Line int
37		Err  error
38	}
39	
40	func (e *Error) Error() string {
41		if e == nil {
42			return "<nil>"
43		}
44	
45		parts := []string{string(e.Kind)}
46		if e.Key != "" {
47			parts = append(parts, "key="+strconv.Quote(e.Key))
48		}
49		if e.Line > 0 {
50			parts = append(parts, fmt.Sprintf("line=%d", e.Line))
51		}
52		if e.Err != nil {
53			parts = append(parts, e.Err.Error())
54		}
55	
56		return "frontmatter: " + strings.Join(parts, ": ")
57	}
58	
59	// Unwrap returns the wrapped error.
60	func (e *Error) Unwrap() error {
61		if e == nil {
62			return nil
63		}
64	
65		return e.Err
66	}
67	
68	// Parse extracts YAML frontmatter from markdown content and returns the decoded
69	// metadata plus the remaining markdown body. When the markdown has no leading
70	// frontmatter block, Parse returns an empty map and the original body.
71	func Parse(markdown string) (map[string]any, string, error) {
72		if !hasOpeningDelimiter(markdown) {
73			return map[string]any{}, markdown, nil
74		}
75	
76		source, body, found := splitFrontmatter(markdown)
77		if !found {
78			return nil, "", &Error{
79				Kind: ErrorKindMissingClosingDelimiter,
80				Err:  fmt.Errorf("missing closing frontmatter delimiter"),
81			}
82		}
83	
84		if strings.TrimSpace(source) == "" {
85			return map[string]any{}, body, nil
86		}
87	
88		var values map[string]any
89		if err := yaml.Unmarshal([]byte(source), &values); err != nil {
90			return nil, "", &Error{
91				Kind: ErrorKindInvalidYAML,
92				Line: extractYAMLLine(err),
93				Err:  err,
94			}
95		}
96	
97		return normalizeMap(values), body, nil
98	}
99	
100	// Generate encodes frontmatter and prepends it to body. When values is empty,
101	// Generate returns body unchanged.
102	func Generate(values map[string]any, body string) (string, error) {
103		if len(values) == 0 {
104			return body, nil
105		}
106	
107		node, err := buildNode(values, "")
108		if err != nil {
109			return "", err
110		}
111	
112		encoded, err := yaml.Marshal(node)
113		if err != nil {
114			return "", fmt.Errorf("marshal frontmatter: %w", err)
115		}
116	
117		return "---\n" + strings.TrimRight(string(encoded), "\n") + "\n---\n" + body, nil
118	}
119	
120	// GetString returns the string value for key, or the zero value when missing.
121	func GetString(values map[string]any, key string) string {
122		value, exists := values[key]
123		if !exists {
124			return ""
125		}
126	
127		switch typed := value.(type) {
128		case string:
129			return typed
130		case fmt.Stringer:
131			return typed.String()
132		default:
133			return fmt.Sprint(typed)
134		}
135	}
136	
137	// GetStringSlice returns the string slice value for key, or nil when missing.
138	func GetStringSlice(values map[string]any, key string) []string {
139		value, exists := values[key]
140		if !exists {
141			return nil
142		}
143	
144		switch typed := value.(type) {
145		case []string:
146			return append([]string(nil), typed...)
147		case []any:
148			items := make([]string, 0, len(typed))
149			for _, item := range typed {
150				text, ok := item.(string)
151				if !ok {
152					return nil
153				}
154				items = append(items, text)
155			}
156			return items
157		default:
158			return nil
159		}
160	}
161	
162	// GetTime returns the time value for key, or the zero time when missing.
163	func GetTime(values map[string]any, key string) time.Time {
164		value, exists := values[key]
165		if !exists {
166			return time.Time{}
167		}
168	
169		switch typed := value.(type) {
170		case time.Time:
171			return typed
172		case string:
173			for _, layout := range []string{DateLayout, time.RFC3339, time.RFC3339Nano} {
174				parsed, err := time.Parse(layout, typed)
175				if err == nil {
176					return parsed
177				}
178			}
179			return time.Time{}
180		default:
181			return time.Time{}
182		}
183	}
184	
185	// GetBool returns the bool value for key, or false when missing.
186	func GetBool(values map[string]any, key string) bool {
187		value, exists := values[key]
188		if !exists {
189			return false
190		}
191	
192		switch typed := value.(type) {
193		case bool:
194			return typed
195		case string:
196			parsed, err := strconv.ParseBool(typed)
197			if err == nil {
198				return parsed
199			}
200			return false
201		default:
202			return false
203		}
204	}
205	
206	func hasOpeningDelimiter(markdown string) bool {
207		return strings.HasPrefix(markdown, "---\n") || strings.HasPrefix(markdown, "---\r\n") || markdown == "---"
208	}
209	
210	func splitFrontmatter(markdown string) (string, string, bool) {
211		start := firstLineEnd(markdown)
212		if start < 0 {
213			return "", "", false
214		}
215	
216		lineStart := start
217		for lineStart <= len(markdown) {
218			lineEnd, next := lineBounds(markdown, lineStart)
219			if strings.TrimSuffix(markdown[lineStart:lineEnd], "\r") == "---" {
220				return markdown[start:lineStart], markdown[next:], true
221			}
222			if next == len(markdown) {
223				break
224			}
225			lineStart = next
226		}
227	
228		return "", "", false
229	}
230	
231	func firstLineEnd(markdown string) int {
232		if strings.HasPrefix(markdown, "---\r\n") {
233			return len("---\r\n")
234		}
235		if strings.HasPrefix(markdown, "---\n") {
236			return len("---\n")
237		}
238		return -1
239	}
240	
241	func lineBounds(markdown string, start int) (int, int) {
242		if start >= len(markdown) {
243			return len(markdown), len(markdown)
244		}
245	
246		index := strings.IndexByte(markdown[start:], '\n')
247		if index < 0 {
248			return len(markdown), len(markdown)
249		}
250	
251		lineEnd := start + index
252		return lineEnd, lineEnd + 1
253	}
254	
255	func normalizeMap(values map[string]any) map[string]any {
256		if len(values) == 0 {
257			return map[string]any{}
258		}
259	
260		normalized := make(map[string]any, len(values))
261		for key, value := range values {
262			normalized[key] = normalizeValue(value)
263		}
264	
265		return normalized
266	}
267	
268	func normalizeValue(value any) any {
269		switch typed := value.(type) {
270		case map[string]any:
271			return normalizeMap(typed)
272		case map[any]any:
273			normalized := make(map[string]any, len(typed))
274			for key, nested := range typed {
275				normalized[fmt.Sprint(key)] = normalizeValue(nested)
276			}
277			return normalized
278		case []any:
279			values := make([]any, len(typed))
280			texts := make([]string, 0, len(typed))
281			allStrings := true
282	
283			for index, item := range typed {
284				normalized := normalizeValue(item)
285				values[index] = normalized
286	
287				text, ok := normalized.(string)
288				if !ok {
289					allStrings = false
290					continue
291				}
292				texts = append(texts, text)
293			}
294	
295			if allStrings {
296				return texts
297			}
298	
299			return values
300		default:
301			return typed
302		}
303	}
304	
305	func buildNode(value any, key string) (*yaml.Node, error) {
306		if value == nil {
307			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}, nil
308		}
309	
310		switch typed := value.(type) {
311		case string:
312			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: typed}, nil
313		case bool:
314			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: strconv.FormatBool(typed)}, nil
315		case time.Time:
316			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!timestamp", Value: formatTime(typed)}, nil
317		case map[string]any:
318			return buildMappingNode(typed)
319		case []string:
320			node := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
321			for _, item := range typed {
322				child, err := buildNode(item, key)
323				if err != nil {
324					return nil, err
325				}
326				node.Content = append(node.Content, child)
327			}
328			return node, nil
329		case []any:
330			node := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
331			for _, item := range typed {
332				child, err := buildNode(item, key)
333				if err != nil {
334					return nil, err
335				}
336				node.Content = append(node.Content, child)
337			}
338			return node, nil
339		}
340	
341		rv := reflect.ValueOf(value)
342		if !rv.IsValid() {
343			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}, nil
344		}
345	
346		switch rv.Kind() {
347		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
348			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.FormatInt(rv.Int(), 10)}, nil
349		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
350			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.FormatUint(rv.Uint(), 10)}, nil
351		case reflect.Float32, reflect.Float64:
352			return &yaml.Node{
353				Kind:  yaml.ScalarNode,
354				Tag:   "!!float",
355				Value: strconv.FormatFloat(rv.Float(), 'f', -1, 64),
356			}, nil
357		case reflect.Map:
358			if rv.Type().Key().Kind() != reflect.String {
359				return nil, &Error{
360					Kind: ErrorKindUnsupportedValue,
361					Key:  key,
362					Err:  fmt.Errorf("map keys must be strings, got %s", rv.Type().Key()),
363				}
364			}
365	
366			values := make(map[string]any, rv.Len())
367			for _, mapKey := range rv.MapKeys() {
368				values[mapKey.String()] = rv.MapIndex(mapKey).Interface()
369			}
370			return buildMappingNode(values)
371		case reflect.Slice, reflect.Array:
372			node := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
373			for index := 0; index < rv.Len(); index++ {
374				child, err := buildNode(rv.Index(index).Interface(), key)
375				if err != nil {
376					return nil, err
377				}
378				node.Content = append(node.Content, child)
379			}
380			return node, nil
381		default:
382			return nil, &Error{
383				Kind: ErrorKindUnsupportedValue,
384				Key:  key,
385				Err:  fmt.Errorf("unsupported value type %T", value),
386			}
387		}
388	}
389	
390	func buildMappingNode(values map[string]any) (*yaml.Node, error) {
391		node := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
392		keys := make([]string, 0, len(values))
393		for key := range values {
394			keys = append(keys, key)
395		}
396		sort.Strings(keys)
397	
398		for _, key := range keys {
399			valueNode, err := buildNode(values[key], key)
400			if err != nil {
401				return nil, err
402			}
403			node.Content = append(node.Content,
404				&yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: key},
405				valueNode,
406			)
407		}
408	
409		return node, nil
410	}
411	
412	func formatTime(value time.Time) string {
413		if value.Hour() == 0 && value.Minute() == 0 && value.Second() == 0 && value.Nanosecond() == 0 {
414			return value.Format(DateLayout)
415		}
416	
417		return value.Format(time.RFC3339Nano)
418	}
419	
420	func extractYAMLLine(err error) int {
421		matches := yamlLinePattern.FindStringSubmatch(err.Error())
422		if len(matches) != 2 {
423			return 0
424		}
425	
426		line, convErr := strconv.Atoi(matches[1])
427		if convErr != nil {
428			return 0
429		}
430	
431		return line
432	}
