26	// ToPosixPath normalizes path separators to forward slashes and trims trailing slashes.
27	func ToPosixPath(value string) string {
28		if value == "" {
29			return ""
30		}
31	
32		normalized := strings.ReplaceAll(value, `\`, `/`)
33		if windowsDriveRootPattern.MatchString(normalized) {
34			return normalized[:2] + "/"
35		}
36	
37		for len(normalized) > 1 && strings.HasSuffix(normalized, "/") {
38			normalized = strings.TrimSuffix(normalized, "/")
39		}
40	
41		if normalized == "" {
42			return "/"
43		}
44	
45		return normalized
46	}
