48	// IsPathInside reports whether targetPath is the same as or nested under parentPath.
49	func IsPathInside(parentPath, targetPath string) bool {
50		parent := cleanComparablePath(parentPath)
51		target := cleanComparablePath(targetPath)
52	
53		switch {
54		case parent == "":
55			return target == ""
56		case target == "":
57			return false
58		}
59	
60		if parent == target {
61			return true
62		}
63	
64		parentDrive, parentParts, parentAbsolute := splitComparablePath(parent)
65		targetDrive, targetParts, targetAbsolute := splitComparablePath(target)
66	
67		if parentAbsolute != targetAbsolute {
68			return false
69		}
70	
71		if !strings.EqualFold(parentDrive, targetDrive) {
72			return false
73		}
74	
75		if len(parentParts) > len(targetParts) {
76			return false
77		}
78	
79		for index := range parentParts {
80			if parentParts[index] != targetParts[index] {
81				return false
82			}
83		}
84	
85		return true
86	}
