98	// SlugifySegment converts a free-form segment into a filesystem-friendly slug.
99	func SlugifySegment(value string) string {
100		trimmed := strings.TrimSpace(strings.ToLower(value))
101		if trimmed == "" {
102			return "item"
103		}
104	
105		var builder strings.Builder
106		lastWasDash := false
107	
108		for _, r := range trimmed {
109			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
110				builder.WriteRune(r)
111				lastWasDash = false
112				continue
113			}
114	
115			if lastWasDash {
116				continue
117			}
118	
119			builder.WriteByte('-')
120			lastWasDash = true
121		}
122	
123		slug := strings.Trim(builder.String(), "-")
124		if slug == "" {
125			return "item"
126		}
127	
128		return slug
129	}
130	
131	// HumanizeSlug converts a hyphenated slug into a title-cased label.
132	func HumanizeSlug(value string) string {
133		if value == "" {
134			return ""
135		}
136	
137		segments := strings.Split(value, "-")
138		humanized := make([]string, 0, len(segments))
139	
140		for _, segment := range segments {
141			if segment == "" {
142				continue
143			}
144	
145			humanized = append(humanized, strings.ToUpper(segment[:1])+segment[1:])
146		}
147	
148		return strings.Join(humanized, " ")
149	}
