270	// OKFLinkFormatter renders relative Markdown links for OKF bundles.
271	type OKFLinkFormatter struct{}
272	
273	// Link renders a GitHub-safe relative Markdown link.
274	func (OKFLinkFormatter) Link(fromDir, targetPath, label string) string {
275		cleanTarget := strings.TrimPrefix(ToPosixPath(strings.TrimSpace(targetPath)), "/")
276		displayLabel := strings.TrimSpace(label)
277		if displayLabel == "" {
278			displayLabel = HumanizeSlug(SlugifySegment(strings.TrimSuffix(path.Base(cleanTarget), ".md")))
279		}
280	
281		fragment := ""
282		if hashIndex := strings.Index(cleanTarget, "#"); hashIndex >= 0 {
283			fragment = cleanTarget[hashIndex:]
284			cleanTarget = cleanTarget[:hashIndex]
285		}
286	
287		cleanFromDir := strings.TrimPrefix(ToPosixPath(strings.TrimSpace(fromDir)), "/")
288		if cleanFromDir == "" {
289			cleanFromDir = "."
290		}
291	
292		relativePath, err := filepath.Rel(filepath.FromSlash(cleanFromDir), filepath.FromSlash(cleanTarget))
293		if err != nil {
294			relativePath = cleanTarget
295		}
296		relativePath = ToPosixPath(relativePath)
297		if relativePath == "." || relativePath == "" {
298			relativePath = path.Base(cleanTarget)
299		}
300		relativePath = strings.TrimPrefix(relativePath, "./")
301		relativePath = markdownLinkTarget(relativePath + fragment)
302		return fmt.Sprintf("[%s](%s)", displayLabel, relativePath)
303	}
