327	func cleanComparablePath(value string) string {
328		normalized := ToPosixPath(value)
329		if normalized == "" || normalized == "/" || windowsDriveRootPattern.MatchString(normalized) {
330			return normalized
331		}
332	
333		return ToPosixPath(path.Clean(normalized))
334	}
