340	func normalizeDocumentPathSegment(value string) string {
341		return strings.TrimLeft(ToPosixPath(value), "/")
342	}
343	
344	func splitComparablePath(value string) (drive string, parts []string, absolute bool) {
345		normalized := value
346		if hasWindowsDrivePrefix(normalized) {
347			drive = normalized[:2]
348			normalized = strings.TrimPrefix(normalized[2:], "/")
349			absolute = true
350		} else {
351			absolute = strings.HasPrefix(normalized, "/")
352			normalized = strings.TrimPrefix(normalized, "/")
353		}
354	
355		if normalized == "" || normalized == "." {
356			return drive, nil, absolute
357		}
358	
359		rawParts := strings.Split(normalized, "/")
360		parts = make([]string, 0, len(rawParts))
361		for _, part := range rawParts {
362			if part == "" || part == "." {
363				continue
364			}
365			parts = append(parts, part)
366		}
367	
368		return drive, parts, absolute
369	}
